1	package config
2	
3	import (
4		"crypto/sha256"
5		"encoding/hex"
6		"fmt"
7		"os"
8		"path/filepath"
9		"reflect"
10		"sort"
11		"strings"
12		"sync"
13		"sync/atomic"
14	
15		"gopkg.in/yaml.v2"
16	
17		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
18	)
19	
20	var (
21		config     *RouterConfig
22		configOnce sync.Once
23		configErr  error
24		configMu   sync.RWMutex
25	
26		configUpdateMu          sync.Mutex
27		configUpdateSubscribers = map[uint64]chan *RouterConfig{}
28		configUpdateNextID      uint64
29	)
30	
31	// Load loads the configuration from the specified YAML file once and caches it globally.
32	func Load(configPath string) (*RouterConfig, error) {
33		configOnce.Do(func() {
34			cfg, err := Parse(configPath)
35			if err != nil {
36				configErr = err
37				return
38			}
39			configMu.Lock()
40			config = cfg
41			configMu.Unlock()
42		})
43		if configErr != nil {
44			return nil, configErr
45		}
46		configMu.RLock()
47		defer configMu.RUnlock()
48		return config, nil
49	}
50	
51	// Parse parses the YAML config file without touching the global cache.
52	func Parse(configPath string) (*RouterConfig, error) {
53		// Resolve symlinks to handle Kubernetes ConfigMap mounts
54		resolved, _ := filepath.EvalSymlinks(configPath)
55		if resolved == "" {
56			resolved = configPath
57		}
58		logging.ComponentDebugEvent("config", "config_parse_started", map[string]interface{}{
59			"path":     configPath,
60			"resolved": resolved,
61		})
62	
63		data, err := os.ReadFile(resolved)
64		if err != nil {
65			logging.ComponentDebugEvent("config", "config_read_failed", map[string]interface{}{
66				"resolved": resolved,
67				"error":    err.Error(),
68			})
69			return nil, fmt.Errorf("failed to read config file: %w", err)
70		}
71		logging.ComponentDebugEvent("config", "config_read_complete", map[string]interface{}{
72			"resolved":   resolved,
73			"size_bytes": len(data),
74		})
75	
76		return parseYAMLBytesWithBaseDir(data, filepath.Dir(resolved))
77	}
78	
79	// ParseYAMLBytes parses config YAML content without touching the filesystem.
80	func ParseYAMLBytes(data []byte) (*RouterConfig, error) {
81		return parseYAMLBytesWithOptions(data, "", true)
82	}
83	
84	func parseYAMLBytesWithBaseDir(data []byte, baseDir string) (*RouterConfig, error) {
85		return parseYAMLBytesWithOptions(data, baseDir, true)
86	}
87	
88	// ParseYAMLBytesWithoutEnvExpansion validates in-memory YAML while preserving
89	// ${VAR} references verbatim. It is intended for read-only validation APIs
90	// that must not expose process environment values in normalized output.
91	func ParseYAMLBytesWithoutEnvExpansion(data []byte) (*RouterConfig, error) {
92		return parseYAMLBytesWithOptions(data, "", false)
93	}
94	
95	func parseYAMLBytesWithOptions(
96		data []byte,
97		baseDir string,
98		expandEnvironment bool,
99	) (*RouterConfig, error) {
100		raw, err := parseRawConfigMap(data)
101		if err != nil {
102			return nil, err
103		}
104		if rejectErr := rejectDeprecatedUserConfigFields(raw); rejectErr != nil {
105			return nil, rejectErr
106		}
107		if rejectErr := rejectRemovedStructureFields(raw); rejectErr != nil {
108			return nil, rejectErr
109		}
110		if rejectErr := rejectRemovedTaxonomyLegacyFields(raw); rejectErr != nil {
111			return nil, rejectErr
112		}
113		if rejectErr := rejectRemovedDecisionToolFields(raw); rejectErr != nil {
114			return nil, rejectErr
115		}
116		if rejectErr := rejectRemovedRouterLearningFields(raw); rejectErr != nil {
117			return nil, rejectErr
118		}
119		if rejectErr := rejectUnsupportedRouterLearningFields(raw); rejectErr != nil {
120			return nil, rejectErr
121		}
122	
123		if expandEnvironment {
124			expandEnvSubstitutionsInMap(raw)
125		}
126		expandedData, marshalErr := yaml.Marshal(raw)
127		if marshalErr != nil {
128			return nil, fmt.Errorf("failed to marshal normalized config input: %w", marshalErr)
129		}
130	
131		// Warn about unknown YAML fields (typos) before parsing into typed structs.
132		WarnUnknownFields(raw, reflect.TypeOf(CanonicalConfig{}))
133	
134		cfg, err := parseRouterConfigPayload(expandedData, raw)
135		if err != nil {
136			return nil, err
137		}
138		cfg.ConfigBaseDir = baseDir
139		documentDigest := sha256.Sum256(data)
140		cfg.DocumentHash = hex.EncodeToString(documentDigest[:])
141		cfg.SkipExternalAssetValidation = !expandEnvironment
142		if err := finalizeParsedConfig(cfg); err != nil {
143			return nil, err
144		}
145	
146		logging.ComponentDebugEvent("config", "config_parse_complete", map[string]interface{}{
147			"decision_count": len(cfg.Decisions),
148			"base_dir":       baseDir,
149		})
150		return cfg, nil
151	}
152	
153	func parseRawConfigMap(data []byte) (map[string]interface{}, error) {
154		var raw map[string]interface{}
155		if unmarshalErr := yaml.Unmarshal(data, &raw); unmarshalErr != nil {
156			logging.ComponentDebugEvent("config", "config_yaml_map_parse_failed", map[string]interface{}{
157				"error": unmarshalErr.Error(),
158			})
159			return nil, fmt.Errorf("failed to parse config file: %w", unmarshalErr)
160		}
161		return raw, nil
162	}
163	
164	func rejectDeprecatedUserConfigFields(raw map[string]interface{}) error {
165		if deprecated := deprecatedUserConfigFields(raw); len(deprecated) > 0 {
166			return fmt.Errorf(
167				"deprecated config fields are no longer supported: %s; rewrite the file to canonical v0.3 providers/routing/global or run `vllm-sr config migrate --config old-config.yaml`",
168				strings.Join(deprecated, ", "),
169			)
170		}
171		return nil
172	}
173	
174	func rejectRemovedStructureFields(raw map[string]interface{}) error {
175		if removed := removedStructureFields(raw); len(removed) > 0 {
176			return fmt.Errorf(
177				"removed config fields are no longer supported: %s; structure density now uses built-in multilingual normalization and no longer accepts feature.normalize_by",
178				strings.Join(removed, ", "),
179			)
180		}
181		return nil
182	}
183	
184	func rejectRemovedTaxonomyLegacyFields(raw map[string]interface{}) error {
185		routing := nestedStringMap(raw["routing"])
186		signals := nestedStringMap(routing["signals"])
187		if _, ok := signals["category_kb"]; ok {
188			return fmt.Errorf(
189				"routing.signals.category_kb is no longer supported; migrate to global.model_catalog.kbs[] plus routing.signals.kb[]",
190			)
191		}
192		if _, ok := signals["taxonomy"]; ok {
193			return fmt.Errorf(
194				"routing.signals.taxonomy is no longer supported; migrate to routing.signals.kb[]",
195			)
196		}
197		global := nestedStringMap(raw["global"])
198		modelCatalog := nestedStringMap(global["model_catalog"])
199		if _, ok := modelCatalog["classifiers"]; ok {
200			return fmt.Errorf(
201				"global.model_catalog.classifiers is no longer supported; migrate to global.model_catalog.kbs[]",
202			)
203		}
204		return nil
205	}
206	
207	func rejectRemovedDecisionToolFields(raw map[string]interface{}) error {
208		routing := nestedStringMap(raw["routing"])
209		decisions, ok := routing["decisions"].([]interface{})
210		if !ok {
211			return nil
212		}
213	
214		removed := make([]string, 0)
215		for index, rawDecision := range decisions {
216			decision := nestedStringMap(rawDecision)
217			for _, field := range []string{"tool_scope", "allow_tools", "block_tools"} {
218				if _, ok := decision[field]; ok {
219					removed = append(removed, fmt.Sprintf("routing.decisions[%d].%s", index, field))
220				}
221			}
222		}
223		if len(removed) == 0 {
224			return nil
225		}
226	
227		return fmt.Errorf(
228			"removed config fields are no longer supported: %s; migrate to routing.decisions[].plugins[type=tools].configuration",
229			strings.Join(removed, ", "),
230		)
231	}
232	
233	func rejectRemovedRouterLearningFields(raw map[string]interface{}) error {
234		global := nestedStringMap(raw["global"])
235		router := nestedStringMap(global["router"])
236		modelSelection := nestedStringMap(router["model_selection"])
237	
238		removedGlobal := make([]string, 0)
239		for _, field := range []string{
240			"session_aware",
241			"model_switch_gate",
242			"lookup_tables",
243			"elo",
244			"rl_driven",
245			"gmtrouter",
246			"bandit",
247			"personalization",
248		} {
249			if _, ok := modelSelection[field]; ok {
250				removedGlobal = append(removedGlobal, "global.router.model_selection."+field)
251			}
252		}
253		if method := strings.TrimSpace(fmt.Sprint(modelSelection["method"])); removedGlobalLearningSelector(method) {
254			removedGlobal = append(removedGlobal, "global.router.model_selection.method="+method)
255		}
256		if len(removedGlobal) > 0 {
257			return fmt.Errorf(
258				"removed config fields are no longer supported: %s; use global.router.learning.adaptation and global.router.learning.protection for cross-request learning",
259				strings.Join(removedGlobal, ", "),
260			)
261		}
262	
263		routing := nestedStringMap(raw["routing"])
264		decisions, ok := routing["decisions"].([]interface{})
265		if !ok {
266			return nil
267		}
268		for index, rawDecision := range decisions {
269			decision := nestedStringMap(rawDecision)
270			if err := rejectRemovedDecisionLearningFields(index, nestedStringMap(decision["algorithm"])); err != nil {
271				return err
272			}
273		}
274		return nil
275	}
276	
277	func rejectRemovedDecisionLearningFields(index int, algorithm map[string]interface{}) error {
278		algorithmType := strings.TrimSpace(fmt.Sprint(algorithm["type"]))
279		if err := removedLearningAlgorithmTypeError(index, algorithmType); err != nil {
280			return err
281		}
282		if _, ok := algorithm["session_aware"]; ok {
283			return fmt.Errorf(
284				"routing.decisions[%d].algorithm.session_aware is no longer supported; remove algorithm.session_aware and configure global.router.learning.protection plus routing.decisions[].adaptations when this decision needs apply/observe/bypass control",
285				index,
286			)
287		}
288		for field, adaptation := range removedDecisionLearningBlocks() {
289			if _, ok := algorithm[field]; ok {
290				return fmt.Errorf(
291					"routing.decisions[%d].algorithm.%s has moved to %s; remove the decision-local learning algorithm block",
292					index,
293					field,
294					adaptation,
295				)
296			}
297		}
298		return nil
299	}
300	
301	func removedLearningAlgorithmTypeError(index int, algorithmType string) error {
302		if algorithmType == "session_aware" {
303			return fmt.Errorf(
304				"routing.decisions[%d].algorithm.type=session_aware is no longer supported; remove algorithm.type=session_aware and enable global.router.learning.protection",
305				index,
306			)
307		}
308		if target, ok := removedDecisionLearningBlocks()[algorithmType]; ok {
309			return fmt.Errorf(
310				"routing.decisions[%d].algorithm.type=%s has moved to %s; remove algorithm.type=%s and choose a request-time base algorithm only when needed",
311				index,
312				algorithmType,
313				target,
314				algorithmType,
315			)
316		}
317		return nil
318	}
319	
320	func removedGlobalLearningSelector(method string) bool {
321		switch strings.TrimSpace(method) {
322		case "session_aware", "lookup_tables", "elo", "rl_driven", "gmtrouter", "bandit", "personalization":
323			return true
324		default:
325			return false
326		}
327	}
328	
329	func removedDecisionLearningBlocks() map[string]string {
330		return map[string]string{
331			"elo":             "global.router.learning.adaptation",
332			"rl_driven":       "global.router.learning.adaptation",
333			"gmtrouter":       "global.router.learning.adaptation",
334			"bandit":          "global.router.learning.adaptation",
335			"personalization": "global.router.learning.adaptation",
336		}
337	}
338	
339	func rejectUnsupportedRouterLearningFields(raw map[string]interface{}) error {
340		if err := rejectUnsupportedGlobalRouterLearningFields(raw); err != nil {
341			return err
342		}
343		return rejectUnsupportedDecisionAdaptationFields(raw)
344	}
345	
346	func rejectUnsupportedGlobalRouterLearningFields(raw map[string]interface{}) error {
347		global := nestedStringMap(raw["global"])
348		router := nestedStringMap(global["router"])
349		learning := nestedStringMap(router["learning"])
350		if len(learning) == 0 {
351			return nil
352		}
353		if err := rejectUnknownMapFields(
354			"global.router.learning",
355			learning,
356			[]string{"enabled", "adaptation", "protection"},
357		); err != nil {
358			return err
359		}
360		if err := rejectUnknownMapFields(
361			"global.router.learning.adaptation",
362			nestedStringMap(learning["adaptation"]),
363			[]string{"enabled", "candidate_set", "strategy"},
364		); err != nil {
365			return err
366		}
367		if err := rejectUnsupportedProtectionLearningFields(
368			"global.router.learning.protection",
369			nestedStringMap(learning["protection"]),
370			[]string{"enabled", "scope", "identity", "tuning"},
371		); err != nil {
372			return err
373		}
374		return nil
375	}
376	
377	func rejectUnsupportedDecisionAdaptationFields(raw map[string]interface{}) error {
378		routing := nestedStringMap(raw["routing"])
379		decisions, ok := routing["decisions"].([]interface{})
380		if !ok {
381			return nil
382		}
383		for index, rawDecision := range decisions {
384			decision := nestedStringMap(rawDecision)
385			adaptations := nestedStringMap(decision["adaptations"])
386			if len(adaptations) == 0 {
387				continue
388			}
389			prefix := fmt.Sprintf("routing.decisions[%d].adaptations", index)
390			if err := rejectUnknownMapFields(prefix, adaptations, []string{"mode", "adaptation", "protection"}); err != nil {
391				return err
392			}
393			if err := rejectUnknownMapFields(
394				prefix+".adaptation",
395				nestedStringMap(adaptations["adaptation"]),
396				[]string{"mode", "candidate_set"},
397			); err != nil {
398				return err
399			}
400			if err := rejectUnknownMapFields(
401				prefix+".protection",
402				nestedStringMap(adaptations["protection"]),
403				[]string{"mode", "stability_weight", "switch_margin"},
404			); err != nil {
405				return err
406			}
407		}
408		return nil
409	}
410	
411	func rejectUnsupportedProtectionLearningFields(prefix string, raw map[string]interface{}, allowed []string) error {
412		if len(raw) == 0 {
413			return nil
414		}
415		if err := rejectUnknownMapFields(prefix, raw, allowed); err != nil {
416			return err
417		}
418		if identity, ok := raw["identity"]; ok {
419			identityMap := nestedStringMap(identity)
420			if err := rejectUnknownMapFields(prefix+".identity", identityMap, []string{"headers"}); err != nil {
421				return err
422			}
423			if err := rejectUnknownMapFields(
424				prefix+".identity.headers",
425				nestedStringMap(identityMap["headers"]),
426				[]string{"session", "conversation"},
427			); err != nil {
428				return err
429			}
430		}
431		if tuning, ok := raw["tuning"]; ok {
432			if err := rejectUnknownMapFields(prefix+".tuning", nestedStringMap(tuning), []string{
433				"idle_timeout_seconds",
434				"min_turns_before_switch",
435				"switch_margin",
436				"stability_weight",
437			}); err != nil {
438				return err
439			}
440		}
441		return nil
442	}
443	
444	func rejectUnknownMapFields(prefix string, raw map[string]interface{}, allowed []string) error {
445		allowedSet := make(map[string]struct{}, len(allowed))
446		for _, key := range allowed {
447			allowedSet[key] = struct{}{}
448		}
449		unknown := make([]string, 0)
450		for key := range raw {
451			if _, ok := allowedSet[key]; !ok {
452				unknown = append(unknown, prefix+"."+key)
453			}
454		}
455		if len(unknown) == 0 {
456			return nil
457		}
458		sort.Strings(unknown)
459		return fmt.Errorf("unsupported Router Learning config fields: %s", strings.Join(unknown, ", "))
460	}
461	
462	func parseRouterConfigPayload(data []byte, raw map[string]interface{}) (*RouterConfig, error) {
463		if !isCanonicalConfig(raw) {
464			return nil, canonicalConfigRequiredError(raw)
465		}
466		return parseCanonicalConfigPayload(data, raw)
467	}
468	
469	func parseCanonicalConfigPayload(data []byte, raw map[string]interface{}) (*RouterConfig, error) {
470		canonical := &CanonicalConfig{}
471		if unmarshalErr := yaml.Unmarshal(data, canonical); unmarshalErr != nil {
472			logging.ComponentDebugEvent("config", "config_canonical_parse_failed", map[string]interface{}{
473				"error": unmarshalErr.Error(),
474			})
475			return nil, fmt.Errorf("failed to parse canonical config file: %w", unmarshalErr)
476		}
477		if err := attachCanonicalGlobalOverride(raw, canonical); err != nil {
478			return nil, err
479		}
480	
481		cfg, err := normalizeCanonicalConfig(canonical)
482		if err != nil {
483			logging.ComponentDebugEvent("config", "config_normalize_failed", map[string]interface{}{
484				"error": err.Error(),
485			})
486			return nil, err
487		}
488		return cfg, nil
489	}
490	
491	func attachCanonicalGlobalOverride(raw map[string]interface{}, canonical *CanonicalConfig) error {
492		rawGlobal, ok := raw["global"]
493		if !ok {
494			return nil
495		}
496	
497		payload, err := NewStructuredPayload(rawGlobal)
498		if err != nil {
499			return fmt.Errorf("failed to encode canonical global override: %w", err)
500		}
501		canonical.globalOverrideRaw = payload
502		return nil
503	}
504	
505	func canonicalConfigRequiredError(raw map[string]interface{}) error {
506		unsupported := unsupportedTopLevelConfigFields(raw)
507		detail := "missing canonical routing/global sections"
508		if len(unsupported) > 0 {
509			detail = fmt.Sprintf("unexpected top-level keys: %s", strings.Join(unsupported, ", "))
510		}
511		return fmt.Errorf(
512			"config file must use canonical v0.3 version/listeners/providers/routing/global; %s; run `vllm-sr config migrate --config old-config.yaml` or rewrite the file to canonical v0.3 providers/routing/global",
513			detail,
514		)
515	}
516	
517	func finalizeParsedConfig(cfg *RouterConfig) error {
518		logParsedDecisions(cfg)
519	
520		// Apply default model registry if not specified in config.
521		// If user specifies mom_registry in config.yaml, it completely replaces the defaults.
522		if len(cfg.MoMRegistry) == 0 {
523			cfg.MoMRegistry = ToLegacyRegistry()
524		}
525		if cfg.VectorStore != nil {
526			cfg.VectorStore.ApplyDefaults()
527		}
528		if err := validateConfigStructure(cfg); err != nil {
529			logging.ComponentDebugEvent("config", "config_validation_failed", map[string]interface{}{
530				"error": err.Error(),
531			})
532			return err
533		}
534		return nil
535	}
536	
537	func logParsedDecisions(cfg *RouterConfig) {
538		decisionNames := make([]string, 0, len(cfg.Decisions))
539		for _, d := range cfg.Decisions {
540			decisionNames = append(decisionNames, d.Name)
541		}
542		logging.ComponentDebugEvent("config", "config_decisions_parsed", map[string]interface{}{
543			"decision_count": len(cfg.Decisions),
544			"decision_names": decisionNames,
545		})
546	}
547	
548	func deprecatedUserConfigFields(raw map[string]interface{}) []string {
549		fields := []string{}
550	
551		routing := nestedStringMap(raw["routing"])
552		if _, ok := routing["models"]; ok {
553			fields = append(fields, "routing.models")
554		}
555	
556		providers := nestedStringMap(raw["providers"])
557		for _, key := range []string{
558			"model_targets",
559			"backends",
560			"auth_profiles",
561			"default_model",
562			"reasoning_families",
563			"default_reasoning_effort",
564		} {
565			if _, ok := providers[key]; ok {
566				fields = append(fields, "providers."+key)
567			}
568		}
569	
570		if models, ok := providers["models"].([]interface{}); ok {
571			for index, rawModel := range models {
572				model := nestedStringMap(rawModel)
573				for _, key := range []string{
574					"access",
575					"endpoints",
576					"access_key",
577					"param_size",
578					"context_window_size",
579					"description",
580					"capabilities",
581					"loras",
582					"quality_score",
583					"modality",
584					"tags",
585				} {
586					if _, ok := model[key]; ok {
587						fields = append(fields, fmt.Sprintf("providers.models[%d].%s", index, key))
588					}
589				}
590			}
591		}
592	
593		global := nestedStringMap(raw["global"])
594		if _, ok := global["modules"]; ok {
595			fields = append(fields, "global.modules")
596		}
597		modelCatalog := nestedStringMap(global["model_catalog"])
598		embeddings := nestedStringMap(modelCatalog["embeddings"])
599		if _, ok := embeddings["bert"]; ok {
600			fields = append(fields, "global.model_catalog.embeddings.bert")
601		}
602	
603		fields = append(fields, deprecatedDecisionConfigFields(routing)...)
604	
605		return fields
606	}
607	
608	func deprecatedDecisionConfigFields(routing map[string]interface{}) []string {
609		decisions, ok := routing["decisions"].([]interface{})
610		if !ok {
611			return nil
612		}
613	
614		fields := make([]string, 0)
615		for index, rawDecision := range decisions {
616			decision := nestedStringMap(rawDecision)
617			if _, ok := decision["modelSelectionAlgorithm"]; ok {
618				fields = append(fields, fmt.Sprintf("routing.decisions[%d].modelSelectionAlgorithm", index))
619			}
620		}
621		return fields
622	}
623	
624	func removedStructureFields(raw map[string]interface{}) []string {
625		routing := nestedStringMap(raw["routing"])
626		signals := nestedStringMap(routing["signals"])
627		structureRules, ok := signals["structure"].([]interface{})
628		if !ok {
629			return nil
630		}
631	
632		fields := make([]string, 0)
633		for index, rawRule := range structureRules {
634			rule := nestedStringMap(rawRule)
635			feature := nestedStringMap(rule["feature"])
636			if _, ok := feature["normalize_by"]; ok {
637				fields = append(fields, fmt.Sprintf("routing.signals.structure[%d].feature.normalize_by", index))
638			}
639		}
640		return fields
641	}
642	
643	func unsupportedTopLevelConfigFields(raw map[string]interface{}) []string {
644		allowed := map[string]bool{
645			"version":   true,
646			"listeners": true,
647			"providers": true,
648			"routing":   true,
649			"global":    true,
650		}
651	
652		fields := make([]string, 0)
653		for key := range raw {
654			if !allowed[key] {
655				fields = append(fields, key)
656			}
657		}
658		sort.Strings(fields)
659		return fields
660	}
661	
662	func nestedStringMap(raw interface{}) map[string]interface{} {
663		switch typed := raw.(type) {
664		case map[string]interface{}:
665			return typed
666		case map[interface{}]interface{}:
667			converted := make(map[string]interface{}, len(typed))
668			for key, value := range typed {
669				keyString, ok := key.(string)
670				if !ok {
671					continue
672				}
673				converted[keyString] = value
674			}
675			return converted
676		default:
677			return map[string]interface{}{}
678		}
679	}
680	
681	// Replace replaces the globally cached config. It is safe for concurrent readers.
682	func Replace(newCfg *RouterConfig) {
683		decisionNames := make([]string, 0, len(newCfg.Decisions))
684		for _, d := range newCfg.Decisions {
685			decisionNames = append(decisionNames, d.Name)
686		}
687		logging.ComponentDebugEvent("config", "config_replace_started", map[string]interface{}{
688			"decision_count": len(newCfg.Decisions),
689			"decision_names": decisionNames,
690		})
691	
692		configMu.Lock()
693		config = newCfg
694		configErr = nil
695		configMu.Unlock()
696	
697		// Notify listeners of config change.
698		configUpdateMu.Lock()
699		subscribers := make(map[uint64]chan *RouterConfig, len(configUpdateSubscribers))
700		for id, ch := range configUpdateSubscribers {
701			subscribers[id] = ch
702		}
703		configUpdateMu.Unlock()
704	
705		if len(subscribers) == 0 {
706			logging.ComponentDebugEvent("config", "config_update_listener_missing", nil)
707			return
708		}
709		for id, ch := range subscribers {
710			select {
711			case ch <- newCfg:
712				logging.ComponentDebugEvent("config", "config_update_notified", map[string]interface{}{
713					"subscriber_id":  id,
714					"decision_count": len(newCfg.Decisions),
715				})
716			default:
717				logging.ComponentWarnEvent("config", "config_update_notification_skipped", map[string]interface{}{
718					"subscriber_id":  id,
719					"reason":         "channel_full",
720					"decision_count": len(newCfg.Decisions),
721				})
722			}
723		}
724	}
725	
726	// Get returns the current configuration
727	func Get() *RouterConfig {
728		configMu.RLock()
729		defer configMu.RUnlock()
730		return config
731	}
732	
733	type ConfigUpdateSubscription struct {
734		ch        chan *RouterConfig
735		closeOnce sync.Once
736		closeFn   func()
737	}
738	
739	func (s *ConfigUpdateSubscription) Updates() <-chan *RouterConfig {
740		if s == nil {
741			return nil
742		}
743		return s.ch
744	}
745	
746	func (s *ConfigUpdateSubscription) Close() {
747		if s == nil {
748			return
749		}
750		s.closeOnce.Do(func() {
751			if s.closeFn != nil {
752				s.closeFn()
753			}
754		})
755	}
756	
757	func SubscribeConfigUpdates(buffer int) *ConfigUpdateSubscription {
758		if buffer <= 0 {
759			buffer = 1
760		}
761	
762		id := atomic.AddUint64(&configUpdateNextID, 1)
763		ch := make(chan *RouterConfig, buffer)
764	
765		configUpdateMu.Lock()
766		configUpdateSubscribers[id] = ch
767		configUpdateMu.Unlock()
768	
769		return &ConfigUpdateSubscription{
770			ch: ch,
771			closeFn: func() {
772				configUpdateMu.Lock()
773				delete(configUpdateSubscribers, id)
774				configUpdateMu.Unlock()
775				close(ch)
776			},
777		}
778	}
779	
780	// WatchConfigUpdates returns a compatibility channel that receives config
781	// updates. New code should prefer SubscribeConfigUpdates so callers can
782	// explicitly release their subscription.
783	func WatchConfigUpdates() <-chan *RouterConfig {
784		return SubscribeConfigUpdates(1).Updates()
785	}
786

