5	// visitRoutingProfileConfigs applies a contract to one isolated routing
6	// profile at a time. It deliberately streams scoped views to the visitor
7	// instead of building an intermediate profile list.
8	func visitRoutingProfileConfigs(cfg *RouterConfig, visit func(*RouterConfig) error) error {
9		if cfg == nil || len(cfg.Recipes) == 0 {
